    // The "prototype_hardener.js:4117" line reveals:
    //   1. The exact filename of the patching infrastructure
    //   2. The line number (which reveals the patch structure)
    //   3. That the function is a JS-defined getter (not native)
    //
    // Fix: Override Error.prototype.stack to return a filtered
    // version when accessed. This catches the default string-based
    // stack (not just Error.prepareStackTrace). We must self-reference
    // this getter in the modifiedFunctions Map to make it appear
    // native to toString inspection.
    //
    // Risk: The patch itself is detectable if our Error.prototype.stack
    // getter is exposed via toString as JS code. Register it in
    // modifiedFunctions so toString() returns "[native code]".
    try {
        const _rawStackDesc = Object.getOwnPropertyDescriptor(Error.prototype, 'stack');
        if (_rawStackDesc && _rawStackDesc.configurable) {
            // Use a regular function (not arrow) so toString() looks
            // more native. The function checks the raw stack getter
            // to avoid infinite recursion.
            const _filteredStackGetter = function() {
                try {
                    // Get the raw stack by calling the original getter
                    // via the prototype's getOwnPropertyDescriptor.
                    // We must use a separate path because we are
                    // OVERRIDING the stack property on the instance
                    // level, so this.stack would loop.
                    const _raw = _rawStackDesc.get.call(this);
                    if (typeof _raw !== 'string') return _raw;
                    // Filter our internal frames. Match any of:
                    //   - "prototype_hardener.js" (our filename)
                    //   - any function/line containing "__sre_" prefix
                    //   - our internal helper function names
                    return _raw.split('\n').filter(line => {
                        return !line.includes('prototype_hardener') &&
                               !line.includes('__sre_') &&
                               !line.includes('safeOverride') &&
                               !line.includes('safePrototype') &&
                               !line.includes('safeProperty') &&
                               !line.includes('verifyCloak') &&
                               !line.includes('shouldSkipJS') &&
                               !line.includes('safeDelete');
                    }).join('\n');
                } catch (e) {
                    // If filtering throws (e.g., raw getter is gone),
                    // return empty string rather than leak the real stack.
                    return '';
                }
            };
            // Mark the getter as native in our registry so toString()
            // returns "[native code]".
            modifiedFunctions.set(_filteredStackGetter,
                "function get stack() { [native code] }");
            // Define on the prototype. We use a getter so that
            // `err.stack = 'foo'` is a no-op (matches native behavior).
            Object.defineProperty(Error.prototype, 'stack', {
                get: _filteredStackGetter,
                configurable: true,
                enumerable: false
            });
        }
    } catch (e) {
        // Error.prototype.stack override is best-effort. Some test
        // environments may not allow the override.
    }

