        client_hints: personaDigest.client_hints || null,
        timezone: personaDigest.timezone || "America/New_York",
        audioSampleRate: personaDigest.audioSampleRate || 48000,
        screenColorDepth: personaDigest.screenColorDepth || 24,
        screenPixelDepth: personaDigest.screenPixelDepth || 24,
        batteryCharging: personaDigest.batteryCharging !== undefined ? personaDigest.batteryCharging : true,
        batteryLevel: personaDigest.batteryLevel || 0.92,
        scrollBehavior: personaDigest.scrollBehavior || "smooth",
        cookieLifetimeDays: personaDigest.cookieLifetimeDays || 14,
        bootId: personaDigest.bootId || "00000000-0000-0000-0000-000000000000",
        uaFullVersion: personaDigest.uaFullVersion || "120.0.6099.109",
        uaMajor: personaDigest.uaMajor || 120,
        platformVersion: personaDigest.platformVersion || "15.0.0",
        architecture: personaDigest.architecture || "x86",
        bitness: personaDigest.bitness || "64",
        mobile: personaDigest.mobile || false,
        model: personaDigest.model || "",
