            "midi": "prompt",
            "camera": "prompt",
            "microphone": "prompt",
            "speaker": "prompt",
            "device-info": "prompt",
            "background-fetch": "prompt",
            "background-sync": "prompt",
            "bluetooth": "prompt",
            "persistent-storage": "prompt",
            "ambient-light-sensor": "prompt",
            "accelerometer": "prompt",
            "gyroscope": "prompt",
            "magnetometer": "prompt",
            "screen-wake-lock": "prompt",
            "nfc": "prompt",
            "display-capture": "prompt",
            "window-management": "prompt",
            "clipboard-read": "prompt",
            // R7-DEEP-AUDIT-2 GAP 1.5: clipboard-write is "granted"
            // by default in real Chrome (no prompt). Returning
