            // has it; in our env it works via the native call.
            if (typeof BaseAudioContext !== "undefined" && BaseAudioContext.prototype.createIIRFilter) {
                modifiedFunctions.set(BaseAudioContext.prototype.createIIRFilter, "function createIIRFilter() {\n    [native code] \n}");
            }
